import { openDB, type IDBPDatabase } from "idb";
import type { Trip } from "./types";

const DAYS = 30;
const DAY = 24 * 60 * 60 * 1000;

// Trips the traveller opened lately, kept on the device so they open without a network.
export class TripCache {
  private db: Promise<IDBPDatabase>;

  constructor(name = "trips") {
    this.db = openDB(name, 1, {
      upgrade(db) {
        const store = db.createObjectStore("trips", { keyPath: "id" });
        store.createIndex("openedAt", "openedAt");
      },
    });
  }

  async put(trip: Trip): Promise<void> {
    const db = await this.db;
    await db.put("trips", { ...trip, openedAt: Date.now() });
    await this.prune();
  }

  async get(id: string): Promise<Trip | undefined> {
    return (await this.db).get("trips", id);
  }

  // Drops trips not opened for DAYS days, oldest first.
  private async prune(): Promise<void> {
    const db = await this.db;
    const old = IDBKeyRange.upperBound(Date.now() - DAYS * DAY);
    for (const key of await db.getAllKeysFromIndex("trips", "openedAt", old)) await db.delete("trips", key);
  }
}

