+import { merchant } from "../config";
+
+// Apple asks the merchant's server, never the browser, for a payment session.
+export async function merchantSession(validationUrl: string, domain: string) {
+  const res = await fetch(validationUrl, {
+    method: "POST",
+    body: JSON.stringify({ merchantIdentifier: merchant.id, displayName: "Acme Trips", initiative: "web", initiativeContext: domain }),
+    agent: merchant.tlsAgent,
+  });
+  if (!res.ok) throw new Error(`Apple Pay validation failed: ${res.status}`);
+  return res.json();
+}

