+// A token bucket per API key: `rate` tokens a second, up to `burst` at once.
+export class Bucket {
+  private tokens: number;
+  private at = Date.now();
+
+  constructor(private rate: number, private burst: number) {
+    this.tokens = burst;
+  }
+
+  take(now = Date.now()): boolean {
+    this.tokens = Math.min(this.burst, this.tokens + ((now - this.at) / 1000) * this.rate);
+    this.at = now;
+    return this.tokens >= 1 ? (this.tokens--, true) : false;
+  }
+}

